#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Buffer {
    int *data;
    size_t count;
};

void buffer_reset(struct Buffer *b) {
    free(b->data);
}

int main(void) {
    struct Buffer b = {NULL, 0};
    char cmd[8];
    while (scanf("%7s", cmd) == 1) {
        if (strcmp(cmd, "fill") == 0) {
            size_t k;
            scanf("%zu", &k);
            buffer_reset(&b);
            b.data = malloc(k * sizeof *b.data);
            if (b.data == NULL) {
                return 1;
            }
            for (size_t i = 0; i < k; i++) {
                b.data[i] = (int)i + 1;
            }
            b.count = k;
        } else if (strcmp(cmd, "sum") == 0) {
            long long sum = 0;
            for (size_t i = 0; i < b.count; i++) {
                sum += b.data[i];
            }
            printf("%lld\n", sum);
        } else {
            buffer_reset(&b);
        }
    }
    buffer_reset(&b);
    return 0;
}

